import{_ as a,o as t,c as n,ak as i}from"./chunks/framework.EzxuW-Mt.js";const u=JSON.parse('{"title":"TeaCon Special Event","description":"","frontmatter":{"title":"TeaCon Special Event","prev":false,"next":false},"headers":[],"relativePath":"en/posts/event/teacon/index.md","filePath":"en/posts/event/teacon/index.md","lastUpdated":1778164094000}'),o={name:"en/posts/event/teacon/index.md"};function r(l,e,s,c,d,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="anvillib-incentive-program-for-teacon" tabindex="-1">AnvilLib - Incentive Program for TeaCon <a class="header-anchor" href="#anvillib-incentive-program-for-teacon" aria-label="Permalink to “AnvilLib - Incentive Program for TeaCon”">​</a></h1><blockquote><p>AnvilLib Incentive Program - Prizes are 3D-printed souvenirs handmade by the author, with no commercial affiliation with TeaCon.</p></blockquote><h2 id="about-this-program" tabindex="-1">About This Program <a class="header-anchor" href="#about-this-program" aria-label="Permalink to “About This Program”">​</a></h2><p>The AnvilLib Incentive Program is a long-term third-party award initiative launched by the author of AnvilLib, aimed at TeaCon participants.</p><p>Starting from TeaCon 2026, during each TeaCon event, this program will establish independent awards to encourage developers to try, dive deep into, and give back to the AnvilLib toolchain. We believe that good tools deserve to be used by more people, and every user and contributor deserves to be taken seriously.</p><p>Whether you are a newcomer just getting started or an experienced developer building stunning creations with AnvilLib, there is a place of honor here for you.</p><h2 id="past-and-current-editions" tabindex="-1">Past and Current Editions <a class="header-anchor" href="#past-and-current-editions" aria-label="Permalink to “Past and Current Editions”">​</a></h2><h3 id="teacon-2026" tabindex="-1">TeaCon 2026 <a class="header-anchor" href="#teacon-2026" aria-label="Permalink to “TeaCon 2026”">​</a></h3><ul><li><p>Status: Ongoing</p></li><li><p>Details: <a href="./2026.html">Click to view the TeaCon 2026 dedicated page</a></p></li><li><p>Winners: To be announced</p></li></ul><p>(Future editions will be continually updated below)</p><h2 id="participation-contact" tabindex="-1">Participation &amp; Contact <a class="header-anchor" href="#participation-contact" aria-label="Permalink to “Participation &amp; Contact”">​</a></h2><ol><li><strong>Use AnvilLib</strong>: Use <a href="https://github.com/Anvil-Dev/AnvilLib" target="_blank" rel="noreferrer">AnvilLib</a> in your development</li><li><strong>Complete your TeaCon entry</strong>: Register and submit your mod normally</li><li><strong>Let us know</strong>: Contact us through the channels below to register, so we can track statistics and distribute prizes</li></ol><p><strong>Contact</strong></p><ul><li>Email: <code>gu_zt@qq.com</code></li><li>QQ PM: 2308465862</li></ul>',14)])])}const b=a(o,[["render",r]]);export{u as __pageData,b as default};
